package com.axiom.integrations.testreport;import com.axiom.integrations.testreport.junit.JUnitXmlTestReportParser;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class JUnitXmlTestReportParserTest {@Test void parsesAndRejectsXxe(){var p=new JUnitXmlTestReportParser();var r=p.parse("x.xml","<testsuite name='s'><testcase classname='C' name='ok' time='0.2'/><testcase classname='C' name='bad'><failure type='AssertionError' message='expected 1'/></testcase></testsuite>".getBytes(),"junit");assertThat(r.total()).isEqualTo(2);assertThat(r.suites().getFirst().testCases().get(1).status().name()).isEqualTo("FAILED");assertThatThrownBy(()->p.parse("x.xml","<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><testsuite name='x'/>".getBytes(),"junit")).isInstanceOf(IllegalArgumentException.class);}}
